ALTER TABLE users ADD COLUMN IF NOT EXISTS banner TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_private BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS links JSONB NOT NULL DEFAULT '[]';
ALTER TABLE users ADD COLUMN IF NOT EXISTS favorites JSONB NOT NULL DEFAULT '[]';
ALTER TABLE users ADD COLUMN IF NOT EXISTS email_verified BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_admin BOOLEAN NOT NULL DEFAULT FALSE;
CREATE UNIQUE INDEX IF NOT EXISTS users_email_ci ON users(lower(email));
CREATE UNIQUE INDEX IF NOT EXISTS users_username_ci ON users(lower(username));
ALTER TABLE books ADD COLUMN IF NOT EXISTS dedupe_key TEXT;
ALTER TABLE books ADD COLUMN IF NOT EXISTS verified BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE books ADD COLUMN IF NOT EXISTS publisher VARCHAR(300);
CREATE UNIQUE INDEX IF NOT EXISTS books_dedupe_unique ON books(dedupe_key) WHERE dedupe_key IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS books_isbn_unique ON books(isbn) WHERE isbn IS NOT NULL AND isbn <> '';
ALTER TABLE shelves DROP CONSTRAINT IF EXISTS shelves_status_check;
ALTER TABLE shelves ADD CONSTRAINT shelves_status_check CHECK(status IN ('lendo','quero-ler','lido','abandonado','pausado'));
ALTER TABLE shelves ADD COLUMN IF NOT EXISTS current_page INTEGER NOT NULL DEFAULT 0 CHECK(current_page >= 0);
ALTER TABLE shelves ADD COLUMN IF NOT EXISTS tags JSONB NOT NULL DEFAULT '[]';
ALTER TABLE shelves ADD COLUMN IF NOT EXISTS started_on DATE;
ALTER TABLE shelves ADD COLUMN IF NOT EXISTS finished_on DATE;
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS spoiler BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
ALTER TABLE follows ADD COLUMN IF NOT EXISTS approved BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE lists ADD COLUMN IF NOT EXISTS cover_url TEXT;
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS auth_tokens(id TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_accounts(provider TEXT NOT NULL,subject TEXT NOT NULL,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(provider,subject));
CREATE TABLE IF NOT EXISTS oauth_states(id TEXT PRIMARY KEY,provider TEXT NOT NULL,verifier TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS reading_history(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,book_id BIGINT NOT NULL REFERENCES books(id) ON DELETE CASCADE,started_on DATE,finished_on DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE INDEX IF NOT EXISTS history_user_date_idx ON reading_history(user_id,finished_on);
CREATE TABLE IF NOT EXISTS goals(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,target INTEGER NOT NULL CHECK(target > 0 AND target <= 10000),starts_on DATE NOT NULL,ends_on DATE NOT NULL,CHECK(ends_on >= starts_on));
ALTER TABLE goals ADD COLUMN IF NOT EXISTS reached BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS notifications(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,actor_id BIGINT REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,content TEXT NOT NULL,review_id BIGINT REFERENCES reviews(id) ON DELETE CASCADE,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS activities(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,book_id BIGINT REFERENCES books(id) ON DELETE CASCADE,kind TEXT NOT NULL,content TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS list_likes(list_id BIGINT NOT NULL REFERENCES lists(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(list_id,user_id));
CREATE TABLE IF NOT EXISTS reports(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,book_id BIGINT REFERENCES books(id) ON DELETE CASCADE,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS follows_target_approved_idx ON follows(following_id,approved);
CREATE INDEX IF NOT EXISTS reviews_feed_idx ON reviews(created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS comments_review_idx ON comments(review_id,created_at);
CREATE INDEX IF NOT EXISTS lists_user_idx ON lists(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS activity_user_idx ON activities(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS auth_tokens_expiry_idx ON auth_tokens(expires_at);
